import java.util.Scanner;

public class Main {

    public void solve() {
        Scanner sc = new Scanner(System.in);
        long W = sc.nextLong();
        long M = sc.nextLong();

        int cur = 0;
        for (; Math.pow(W, cur) < M; cur++);
        double pw = Math.pow(W, cur);

        boolean yes = false;
        if (pw == M) {
            yes = true;
        } else {
            long max = (long) pw;
            long sum = (max - 1) / (W - 1);
            if (max - sum == M) {
                yes = true;
            } else {
                yes = dfs(W, M);
            }
        }

        System.out.println(yes ? "YES" : "NO");
    }

    private boolean dfs(long W, long M) {
        if (M == 1) {
            return true;
        }
        if (M % W == 0) {
            return dfs(W, M / W);
        } else if ((M - 1) % W == 0) {
            return dfs(W, (M - 1) / W);
        } else if ((M + 1) % W == 0) {
            return dfs(W, (M + 1) / W);
        }
        return false;
    }

    public static void main(String[] args) {
        new Main().solve();
    }
}
